<?php
declare(strict_types=1);
$root=__DIR__.'/.fixed-price-sandbox'; @mkdir($root); @mkdir($root.'/includes'); @mkdir($root.'/storage');
copy(__DIR__.'/../../functions.php',$root.'/functions.php');
foreach (['invoice_catalog.php','invoice_voice_learning.php','logger.php','email_transport.php'] as $f) copy(__DIR__.'/../../includes/'.$f,$root.'/includes/'.$f);
file_put_contents($root.'/storage/.htaccess',"Require all denied\n");
require $root.'/functions.php'; require $root.'/includes/invoice_catalog.php'; require $root.'/includes/invoice_voice_learning.php';
$n=0; $check=static function(bool $ok,string $message)use(&$n):void{$n++;if(!$ok)throw new RuntimeException($message);};
$actor=['id'=>str_repeat('a',32),'name'=>'Admin Test'];
$create=['article'=>['name'=>'Glasbyte','unit'=>'st','price'=>'750']];
$first=portal_invoice_catalog_save($create,false); $check($first['ok'],'Staff may create ordinary catalog entries');
$id=$first['id'];
$attempt=['article'=>['id'=>$id,'name'=>'Glasbyte','unit'=>'st','price'=>'750','fixed_price'=>'1']];
$check((portal_invoice_catalog_save($attempt,false)['code']??'')==='admin_required','Staff cannot mark an item fixed through a crafted POST');
$check((portal_invoice_catalog_save($attempt,true)['code']??'')==='history_actor','Fixed changes require a trusted actor');
$check(portal_invoice_catalog_price_history(portal_invoice_catalog_read())===[],'A failed change creates no history');
$check(portal_invoice_catalog_save($attempt,true,$actor)['ok'],'Admin can explicitly mark fixed');
$history=portal_invoice_catalog_price_history(portal_invoice_catalog_read());
$check(count($history)===1 && $history[0]['action']==='enabled' && $history[0]['actor_name']==='Admin Test' && $history[0]['actor_id']===$actor['id'], 'Enabling fixed price records the authenticated administrator');
$check(count(portal_invoice_catalog_list())===1 && !isset(portal_invoice_catalog_list()[0]['events']), 'Audit metadata is excluded from user and voice catalog');

$fixed=portal_invoice_catalog_list(); $check($fixed[0]['fixed_price']===true,'Fixed designation persists');
$check((portal_invoice_catalog_save(['article'=>['id'=>$id,'name'=>'Glasbyte','unit'=>'st','price'=>'1']],false)['code']??'')==='admin_required','Staff cannot alter fixed items even without fixed flag');
$check((portal_invoice_catalog_delete($id,false)['code']??'')==='admin_required','Staff cannot delete a fixed item');
$check((portal_invoice_catalog_save(['article'=>['name'=>'glasbyte','unit'=>'tim','price'=>'3']],false)['code']??'')==='fixed_duplicate','Fixed descriptions cannot be duplicated even with another unit or case');
$item=['art'=>'GLASBYTE','qty'=>2.0,'unit'=>'st','price'=>750.0];
$check(portal_invoice_catalog_validate_fixed([$item],[],$fixed),'Correct fixed price is accepted');
$stamped=portal_invoice_catalog_enforce_fixed([$item],[],$fixed); $locked=$stamped[0]??[];
$check(isset($locked['fixed_lock']) && preg_match('/\A[a-f0-9]{32}\z/D', $locked['fixed_lock'])===1, 'Saving creates a stable historical fixed-price lock');
$prior=['items'=>[$locked]];
$check(portal_invoice_catalog_validate_fixed([$locked],$prior,[]),'A saved fixed-price row stays locked even if catalog item is later removed');
$changedLock=$locked; $changedLock['price']=5.0;
$check(!portal_invoice_catalog_validate_fixed([$changedLock],$prior,[]),'A crafted price change to a saved locked row is rejected after catalog deletion');
$changedLock=$locked; $changedLock['art']='Annat namn';
$check(!portal_invoice_catalog_validate_fixed([$changedLock],$prior,[]),'The identity of a saved fixed row cannot be changed');
$changedLock=$locked; $changedLock['qty']=3.0;
$check(portal_invoice_catalog_validate_fixed([$changedLock],$prior,[]),'Quantity can change without changing fixed unit price');
$check(!portal_invoice_catalog_validate_fixed([$locked,$locked],$prior,[]),'A saved fixed lock cannot be reused on multiple rows');

$modified=$item; $modified['price']=100.0;
$check(!portal_invoice_catalog_validate_fixed([$modified],[],$fixed),'Crafted invoice price cannot override fixed price');
$modified=$item; $modified['price']=750.001;
$check(!portal_invoice_catalog_validate_fixed([$modified],[],$fixed),'Extra precision cannot bypass a fixed price');
$modified=$item; $modified['unit']='tim';
$check(!portal_invoice_catalog_validate_fixed([$modified],[],$fixed),'Changing unit cannot bypass fixed price');
$other=['art'=>'Arbete','qty'=>1.0,'unit'=>'tim','price'=>100.0];
$check(portal_invoice_catalog_validate_fixed([$other],[],$fixed),'Unrelated variable-price items remain editable');
$old=['items'=>[['art'=>'Glasbyte','unit'=>'st','qty'=>2,'price'=>600.0]]];
$historical=$item; $historical['price']=600.0;
$check(portal_invoice_catalog_validate_fixed([$historical],$old,$fixed),'A saved historical price remains unchanged after a catalog update');
$check(!portal_invoice_catalog_validate_fixed([$historical,$historical],$old,$fixed),'Old price cannot be duplicated onto another new line');
$check(!portal_voice_learning_may_learn_price('glasbyte','glasbyte'),'Fixed unit prices never enter price learning');
$user=str_repeat('d',32);$learning=portal_voice_learning_empty();$learning['learning']=true;$learning['auto']=true;$learning['numeric_learning']=true;$learning['reviewed']=50;
save_data(portal_voice_learning_path($user),$learning);
$auto=portal_voice_learning_update($user,'track_auto',['heard'=>'Glasbyte','approved'=>'Glasbyte','numeric_qty'=>'1','numeric_price'=>'750','numeric_unit'=>'st']);
$corrected=portal_voice_learning_update($user,'sync_auto',['voice_token'=>$auto['token'],'approved'=>'Glasbyte','numeric_qty'=>'2','numeric_price'=>'600','numeric_unit'=>'st']);
$check($corrected['ok'] && count($corrected['profile']['numeric_corrections'])===1 && $corrected['profile']['numeric_corrections'][0]['field']==='qty','Fixed price corrections are not learned even from a crafted request; quantity learning continues');

$check(portal_voice_learning_may_learn_price('Arbete','Arbete'),'Other prices may be learned after opt-in');
$duplicate=$fixed; $duplicate[]=['id'=>str_repeat('a',32),'name'=>'glasbyte','unit'=>'tim','price'=>500.0,'fixed_price'=>false];
$check(!portal_invoice_catalog_validate_fixed([$item],[],$duplicate),'Ambiguous legacy catalog conflicts fail closed');
$check(portal_invoice_catalog_fixed_rules([['fixed_price'=>'true']])===null,'Malformed fixed configuration fails closed');
$check(portal_invoice_catalog_save(['article'=>['id'=>$id,'name'=>'Glasbyte','unit'=>'st','price'=>'850','fixed_price'=>'1']],true,$actor)['ok'],'Admin can explicitly update catalog price');
$history=portal_invoice_catalog_price_history(portal_invoice_catalog_read());
$check(count($history)===2 && $history[1]['action']==='changed' && (float)$history[1]['old_price']===750.0 && (float)$history[1]['new_price']===850.0 && $history[1]['old_unit']==='st', 'Fixed price changes capture old, new and unit');
$check(portal_invoice_catalog_validate_fixed([$locked],$prior,portal_invoice_catalog_list()), 'Existing locked invoices keep their historical price after catalog update');

$check(portal_invoice_catalog_save(['article'=>['id'=>$id,'name'=>'Glasbyte','unit'=>'st','price'=>'850','fixed_price'=>'1','aliases'=>"Rutbyte\nVindrutebyte"]],true,$actor)['ok'],'Admin saves aliases');
$rules=portal_invoice_catalog_list(); $check($rules[0]['aliases']===['Rutbyte','Vindrutebyte'],'Aliases persist and old catalog data normalizes');
$check(count(portal_invoice_catalog_price_history(portal_invoice_catalog_read()))===2,'Alias-only changes do not invent price changes');
$aliasItem=['art'=>'RUTBYTE','qty'=>2,'unit'=>'st','price'=>850];
$check(portal_invoice_catalog_validate_fixed([$aliasItem],[],$rules),'Alias matches fixed item on server');
$aliasItem['price']=3; $check(!portal_invoice_catalog_validate_fixed([$aliasItem],[],$rules),'Alias cannot bypass fixed price');
$aliasItem['price']=850;$aliasItem['unit']='tim';$check(!portal_invoice_catalog_validate_fixed([$aliasItem],[],$rules),'Alias cannot bypass fixed unit');
$check(!portal_voice_learning_may_learn_price('rutbyte','annat'),'Fixed price learning rejects aliases');
$check((portal_invoice_catalog_save(['article'=>['name'=>'Rutbyte','unit'=>'st','price'=>'1']],false)['code']??'')==='alias_duplicate','Other items cannot use a reserved alias');
$check((portal_invoice_catalog_save(['article'=>['name'=>'Annat','unit'=>'st','price'=>'1','aliases'=>'rutbyte']],true,$actor)['code']??'')==='alias_duplicate','Other aliases cannot collide');
$check((portal_invoice_catalog_save(['article'=>['name'=>'Annat','unit'=>'st','price'=>'1','aliases'=>'Eget']],false)['code']??'')==='admin_required','Non-admin cannot set aliases');
$check((portal_invoice_catalog_save(['article'=>['name'=>'Annat','unit'=>'st','price'=>'1','aliases'=>"dubbel\nDUBBEL"]],true,$actor)['code']??'')==='invalid_alias','Duplicate aliases rejected');
$var=portal_invoice_catalog_save(['article'=>['name'=>'Arbete','unit'=>'tim','price'=>'2','aliases'=>'Jobb']],true,$actor); $check($var['ok'],'Admin adds alias to variable item');
$check(portal_invoice_catalog_save(['article'=>['id'=>$var['id'],'name'=>'Arbete','unit'=>'tim','price'=>'3']],false)['ok'],'Staff can edit variable item without alias access');
$after=portal_invoice_catalog_list();$found=array_values(array_filter($after,static fn($a)=>$a['id']===$var['id']));$check($found[0]['aliases']===['Jobb'],'Staff edits preserve existing aliases');
$check(portal_invoice_catalog_fixed_rules([['fixed_price'=>true,'aliases'=>'wrong']])===null,'Malformed alias storage fails closed');
$intact=portal_invoice_catalog_read(); $corrupt=$intact;
foreach ($corrupt as &$record) if (($record['record_type'] ?? '') === 'portal_fixed_price_history') $record['events']=[['bad'=>true]];
unset($record);
$check(save_data(portal_invoice_catalog_path(),$corrupt),'Corrupt history fixture written');
$blocked=portal_invoice_catalog_save(['article'=>['id'=>$id,'name'=>'Glasbyte','unit'=>'st','price'=>'999','fixed_price'=>'1']],true,$actor);
$check(($blocked['code']??'')==='history_error' && portal_invoice_catalog_read()===$corrupt, 'Corrupt history blocks fixed-price update without changing catalog');
$check(portal_invoice_catalog_validate_fixed([$aliasItem],[],portal_invoice_catalog_fixed_rules($corrupt))===false, 'Fixed-price enforcement stays active with broken history');
$check(save_data(portal_invoice_catalog_path(),$intact),'Restore valid history fixture');
$speaker=str_repeat('e',32); $numericProfile=portal_voice_learning_empty();$numericProfile['learning']=true;$numericProfile['auto']=true;$numericProfile['numeric_learning']=true;$numericProfile['reviewed']=50; save_data(portal_voice_learning_path($speaker),$numericProfile);
$withoutPrice=portal_voice_learning_update($speaker,'track_auto',['heard'=>'Rutbyte','approved'=>'Glasbyte','numeric_qty'=>'2','numeric_unit'=>'st']);
$check($withoutPrice['ok'],'Quantity-only speech can be tracked with numeric learning enabled');
$learnedQty=portal_voice_learning_update($speaker,'sync_auto',['voice_token'=>$withoutPrice['token'],'approved'=>'Glasbyte','numeric_qty'=>'3','numeric_price'=>'850','numeric_unit'=>'st']);
$check($learnedQty['ok'] && count($learnedQty['profile']['numeric_corrections'])===1 && $learnedQty['profile']['numeric_corrections'][0]['field']==='qty', 'Quantity change learned when no price was spoken');
$check(portal_invoice_catalog_delete($id,true,$actor)['ok'],'Admin can explicitly delete fixed item');
$history=portal_invoice_catalog_price_history(portal_invoice_catalog_read());
$check(count($history)===3 && $history[2]['action']==='deleted' && $history[2]['actor_id']===$actor['id'], 'History and deletion entry survive removal from catalog');
$check(count(portal_invoice_catalog_list())===1 && portal_invoice_catalog_list()[0]['name']==='Arbete', 'Deleted item and audit are not selectable');
$bad=[['record_type'=>'portal_fixed_price_history','events'=>[['oops'=>true]]]];
$check(portal_invoice_catalog_price_history($bad)===null,'Malformed history fails safely');
$records=portal_invoice_catalog_read(); $sentinel=array_values(array_filter($records, static fn($r)=>($r['record_type']??'')==='portal_fixed_price_history'))[0];
$check(portal_invoice_catalog_price_history([$sentinel,$sentinel])===null,'Duplicate history records are rejected');
$check(portal_invoice_catalog_fixed_rules($bad)!==null,'A malformed history alone does not disable invoice fixed-price enforcement');
$check(portal_invoice_catalog_append_history($bad, [], ['id'=>str_repeat('b',32),'name'=>'Nytt','unit'=>'st','price'=>1,'fixed_price'=>true], $actor)==='history_error','Corrupt history blocks unlogged fixed-price changes');

$later=portal_voice_learning_update($speaker,'sync_auto',['voice_token'=>$learnedQty['token'],'approved'=>'Glasbyte','numeric_qty'=>'3','numeric_price'=>'999','numeric_unit'=>'st']);
$check($later['ok'] && count($later['profile']['numeric_corrections'])===1 && $later['profile']['numeric_corrections'][0]['field']==='qty','A catalog-derived price is never learned as spoken even after item deletion');
foreach(glob($root.'/storage/*')?:[] as $f)unlink($f); unlink($root.'/storage/.htaccess');rmdir($root.'/storage');foreach(glob($root.'/includes/*')?:[] as $f)unlink($f);rmdir($root.'/includes');unlink($root.'/functions.php');rmdir($root);
echo "PASS: $n fixed-price permission and server validation checks.\n";
